{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Publicly accessible database instance",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The database instance allows access from 0.0.0.0/0, which exposes it to the entire internet. This is a significant security risk as it increases the attack surface."
    },
    {
      "check_id": "UNKNOWN",
      "title": "SSL not enforced for database connections",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The database instance does not enforce SSL connections (`require_ssl = false`), which can lead to unencrypted data transmission and potential data interception."
    },
    {
      "check_id": "CKV_GCP_121",
      "title": "Deletion protection not enabled for database instance",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "Deletion protection is disabled, which increases the risk of accidental or malicious deletion of the database instance."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n  }\n  deletion_protection = true\n}",
  "fix_summary": "Removed the public IP access (0.0.0.0/0) from the authorized networks, enforced SSL connections by setting `require_ssl = true`, and enabled deletion protection for the database instance."
}
